@use 'tokens';

// ==========================================
// 可选默认主题
// ==========================================

:root,
.light,
[data-theme='light'] {
	color-scheme: light;
	--background: #ffffff;
	--foreground: #18181b;
	--card: #ffffff;
	--card-foreground: #18181b;
	--popover: #ffffff;
	--popover-foreground: #18181b;
	--primary: #18181b;
	--primary-foreground: #fafafa;
	--secondary: #f4f4f5;
	--secondary-foreground: #18181b;
	--muted: #f4f4f5;
	--muted-foreground: #71717a;
	--accent: #f4f4f5;
	--accent-foreground: #18181b;
	--destructive: #ef4444;
	--destructive-foreground: #fafafa;
	--border: #e4e4e7;
	--input: #e4e4e7;
	--ring: #18181b;
	--chart-1: #e76e50;
	--chart-2: #2a9d90;
	--chart-3: #274754;
	--chart-4: #e8c468;
	--chart-5: #f4a462;
	--sidebar: var(--card);
	--sidebar-foreground: var(--card-foreground);
	--sidebar-primary: var(--primary);
	--sidebar-primary-foreground: var(--primary-foreground);
	--sidebar-accent: var(--accent);
	--sidebar-accent-foreground: var(--accent-foreground);
	--sidebar-border: var(--border);
	--sidebar-ring: var(--ring);
	--radius: 0.5rem;
}

.dark,
[data-theme='dark'] {
	color-scheme: dark;
	--background: #09090b;
	--foreground: #fafafa;
	--card: #09090b;
	--card-foreground: #fafafa;
	--popover: #09090b;
	--popover-foreground: #fafafa;
	--primary: #fafafa;
	--primary-foreground: #18181b;
	--secondary: #27272a;
	--secondary-foreground: #fafafa;
	--muted: #27272a;
	--muted-foreground: #a1a1aa;
	--accent: #27272a;
	--accent-foreground: #fafafa;
	--destructive: #7f1d1d;
	--destructive-foreground: #fafafa;
	--border: #27272a;
	--input: #27272a;
	--ring: #d4d4d8;
	--chart-1: #2662d9;
	--chart-2: #2eb88a;
	--chart-3: #e88c30;
	--chart-4: #af57db;
	--chart-5: #e23670;
}
